		resp = await approvalHandler({
			toolName: "subagent",
			action: LARGE_SUBAGENT_LAUNCH_ACTION,
			detail: `large subagent launch (${count} children)${launchSummary || summary ? `\n${launchSummary || summary}` : ""}`,
			kind: "large-subagent-launch",
		});
